entries[225123] = { ["name"] = "Kristalline Schockwelle", ["text"] = "Ca. 2 Procs pro Minute\nEure Angriffe haben eine Chance, eine Schaden verursachende Schockwelle auszulösen, die Gegnern vor Euch 771 körperlichen Schaden zufügt." }
entries[225124] = { ["name"] = "Sande der Zeit", ["text"] = "1 sek. Abklingzeit\nAbsorbiert bis zu 53269 Schaden eines Angriffs, der Euch töten würde. Wenn dieser Effekt auftritt, werdet Ihr sofort um 3987 Gesundheit geheilt und erleidet danach im Verlauf von 10 Sek. den gesamten verhinderten Schaden. Dies kann nur einmal alle 6 Min. geschehen." }
entries[225125] = { ["name"] = "Accelerando", ["text"] = "Ca. 12 Procs pro Minute\nEure Schadenszauber haben eine Chance, Euch 12 Sek. lang 35 Tempo zu gewähren. Dieser Effekt ist bis zu 5-mal stapelbar. Die einzelnen Stapel erneuern nicht die Effektdauer." }
entries[225126] = { ["name"] = "Köstlicher Kuchen!", ["text"] = "3 Meter Reichweite\nSofort 2 min Abklingzeit\nErschafft für 20 Sek. ein magisches Festmahl. Bis zu 5 Verbündete, die am Festmahl teilnehmen, absorbieren 12 Sek. lang 4001 Schaden." }
entries[225127] = { ["name"] = "Arkaner Hieb", ["text"] = "1 sek. Abklingzeit\nCa. 5 Procs pro Minute\nEure Nahkampfangriffe haben eine Chance, alle Gegner vor Euch zu zerfetzen und ihnen 324 Arkanschaden zuzufügen." }
entries[225128] = { ["name"] = "Gelassenheit des Nachtbrunnens", ["text"] = "Ca. 3 Procs pro Minute\nEure Heilzauber haben eine Chance, dem Ziel 'Gelassenheit des Nachtbrunnens' zu gewähren, die im Verlauf von 12 Sek. 1342 Gesundheit regeneriert. Das Heilen eines Ziels, das von 'Gelassenheit des Nachtbrunnens' betroffen ist, kann eine Detonation auslösen, die Verbündete in der Nähe um 224 Gesundheit heilt." }
entries[225129] = { ["name"] = "Triumvirat", ["text"] = "Ca. 0.7 Procs pro Minute\nEure Nahkampf- und Distanzangriffe haben eine Chance, Euch für 20 Sek. eine Feuer-, Frost- oder Arkanverzauberung zu gewähren." }
entries[225130] = { ["name"] = "Vampiraura", ["text"] = "Sofort 1 min Abklingzeit\nGewinnt für 12 Sek. 228 Lebensraub." }
entries[225131] = { ["name"] = "Aasschwarm", ["text"] = "100 Meter Reichweite\nCa. 1.5 Procs pro Minute\nEure Distanzangriffe und Zauber haben eine Chance, einen Aasschwarm zu entfesseln, der alle Gegner in einer Linie vor Euch infiziert und ihnen im Verlauf von 8 Sek. ( 471 * 4) Schattenschaden zufügt." }
entries[225132] = { ["name"] = "Kolossales Schmettern", ["text"] = "Sofort 1 min Abklingzeit\nEntfesselt ein kolossales Schmettern, das immer kritisch trifft und 2671 körperlichen Schaden verursacht, der gleichmäßig unter allen Gegnern in der Nähe aufgeteilt wird. Wenn Ihr weniger als 3 Ziele trefft, wird die Abklingzeit der Fähigkeit um 15 Sek. verringert." }
entries[225133] = { ["name"] = "Sphäre der Zerstörung", ["text"] = "10 - 40 Meter Reichweite\nSofort 1 min Abklingzeit\nEntsendet eine Sphäre der Zerstörung zur Position Eures Ziels in mindestens 10 Metern Entfernung, die nach 4 Sek. allen Gegnern innerhalb von 20 Metern 3071 Schattenschaden zufügt. Ziele, die sich näher an der Explosion befinden, erleiden mehr Schaden." }
entries[225134] = { ["name"] = "Solarkollaps", ["text"] = "Ca. 2 Procs pro Minute\nEure Distanzangriffe und Zauber haben eine Chance, an der Position Eures Ziels einen Solarkollaps hervorzurufen, der nach 3 Sek. Gegnern in der Nähe 1413 Feuerschaden zufügt.\n(3s Abklingzeit)" }
entries[225135] = { ["name"] = "Rekursive Schläge", ["text"] = "Ca. 1 Procs pro Minute\nEure Angriffe haben eine Chance, dass Euch 15 Sek. lang der Effekt 'Rekursive Schläge' gewährt wird, wodurch Eure automatischen Angriffe zusätzlich 161 Schaden verursachen und die Intensität von 'Rekursive Schläge' erhöht wird." }
entries[225136] = { ["name"] = "Konstellationen", ["text"] = "1 sek. Abklingzeit\nCa. 2 Procs pro Minute\nEure Heilzauber haben eine Chance, Eure Meisterschaft, Euer Tempo oder Euren kritischen Trefferwert für 8 Sek. um 207 zu erhöhen." }
entries[225137] = { ["name"] = "Sternentor", ["text"] = "Ca. 3 Procs pro Minute\nEure Schadenszauber haben eine Chance, einen Meteor aus dem Wirbelnden Nether herabzurufen, der Eurem Ziel und allen Gegnern in der Nähe 496 Zauberfeuerschaden zufügt." }
entries[225138] = { ["name"] = "Zeitverschiebung", ["text"] = "Ca. 1.2 Procs pro Minute\nEure Heilzauber haben eine Chance, Euren nächsten Einsatz eines direkten Heilzaubers 79 Mana wiederherstellen zu lassen, anstatt Mana zu kosten." }
entries[225139] = { ["name"] = "Voraussicht", ["text"] = "Ca. 3 Procs pro Minute\nEure Angriffe haben eine Chance, die verbleibende Abklingzeit einer Eurer mächtigen Fähigkeiten um 3 Sek. zu verringern. Gilt nicht für Eure Spezialisierung." }
entries[225140] = { ["name"] = "Höllischer Vertrag", ["text"] = "Sofort 2 min Abklingzeit\nVerringert sämtlichen erlittenen Schaden 20 Sek. lang um 50%, bis zu maximal [ 22024 * (1 + Vielseitigkeit)] verhindertem Schaden. Wenn dieser Effekt abläuft, erleidet Ihr 30 Sek. lang 20% zusätzlichen Schaden als Feuerschaden, bis zu maximal 33945 zusätzlichem Schaden." }
entries[225141] = { ["name"] = "Teuflische Wut", ["text"] = "Kanalisiert (Wirken in 3 sek.) 1.333 min Abklingzeit\nVerfällt in eine teuflische Wut und fügt einem zufälligen Gegner in der Nähe 3 Sek. lang alle 0.25 Sek. 752 Schattenschaden zu. Während die Wut anhält, könnt Ihr Euch weder bewegen noch Fähigkeiten einsetzen." }
entries[225142] = { ["name"] = "Perfider Pakt", ["text"] = "Ca. 0.7 Procs pro Minute\nEure Schadenszauber haben eine Chance, den Effekt 'Perfider Pakt' auszulösen, der Euer Zaubertempo 12 Sek. lang um 1 % erhöht. Wenn 'Perfider Pakt' abläuft, wird Euer Zaubertempo für 8 Sek. um 1 % verringert.\n(20s Abklingzeit)" }
