entries[225522] = { ["name"] = "Glyphe 'Gesprungenes Eis'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (10), Rosenrote Pigmente (30)\nStellt eine Glyphe 'Gesprungenes Eis' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Todesritter\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBei Eurem Einsatz von 'Eisige Pfade' sieht das Eis jetzt ein wenig gesprungen aus. Nur ein wenig. Exklusiv mit: Glyphe 'Trockeneis'\n11" }
entries[225524] = { ["name"] = "Glyphe 'Eiskalte Hülle'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (10), Rosenrote Pigmente (30)\nStellt eine Glyphe 'Eiskalte Hülle' her.\nBeute von:\nWasserelementare der Verheerten Inseln\n\nKlassen: Todesritter\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure antimagische Hülle verändert sich, um sich der Vorliebe für Frost anzupassen. Exklusiv mit: Glyphe 'Blutrote Hülle'\n11" }
entries[225525] = { ["name"] = "Glyphe 'Blutrote Hülle'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (10), Rosenrote Pigmente (30)\nStellt eine Glyphe 'Blutrote Hülle' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Todesritter\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure antimagische Hülle verändert sich, um sich der Vorliebe für Blut anzupassen. Exklusiv mit: Glyphe 'Eiskalte Hülle'\n11" }
entries[225527] = { ["name"] = "Glyphe 'Teufelsschwingen'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (12), Rosenrote Pigmente (20)\nStellt eine Glyphe 'Teufelsschwingen' her.\nBeute von:\nDämonenbestien der Verheerten Inseln\n\nKlassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Gleiten aktiv ist, habt Ihr nun grüne Flügel. Exklusiv mit: Glyphe 'Fahle Flügel' Glyphe 'Zerfledderte Flügel'\n11" }
entries[225528] = { ["name"] = "Glyphe 'Teufelsfeinde'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (12), Rosenrote Pigmente (20)\nStellt eine Glyphe 'Teufelsfeinde' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Geistersicht' wird durch Teufelsenergie verändert, sodass Ihr alle Gegner in einem Teufelslicht seht.\n11" }
entries[225529] = { ["name"] = "Glyphe 'Manaberührte Seelen'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (12), Rosenrote Pigmente (20)\nStellt eine Glyphe 'Manaberührte Seelen' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure zerschmetterten Seelen sind mit Mana befleckt. Exklusiv mit: Glyphe 'Teufelsberührte Seelen'\n11" }
entries[225530] = { ["name"] = "Glyphe 'Schattenfeinde'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (12), Rosenrote Pigmente (20)\nStellt eine Glyphe 'Schattenfeinde' her.\nVerkäufer:\nOxana Dämonstod\nZone:\nKanalisation von Dalaran\nKosten:\n100\n\nKlassen: Dämonenjäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure 'Geistersicht' ist durch die Leere verdunkelt, sodass Ihr Gegner in Schatten gehüllt seht.\n11" }
entries[225531] = { ["name"] = "Glyphe 'Hirschkuh'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)\nStellt eine Glyphe 'Hirschkuh' her.\nBeute von:\nWeltkreaturen der Verheerten Inseln\n\nKlassen: Druide\nBenutzen: Schaltet die Option für die Hirschkuh als Reisegestalt beim Barbier frei.\n11" }
entries[225532] = { ["name"] = "Glyphe 'Wildes Chamäleon'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)\nStellt eine Glyphe 'Wildes Chamäleon' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr Katzengestalt annehmt, wird Eure verwandelte Gestalt zufällig ausgewählt.\n11" }
entries[225533] = { ["name"] = "Glyphe 'Waldpfad'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)\nStellt eine Glyphe 'Waldpfad' her.\nVerkäufer:\nLorelae Winterklang\nZone:\nMondlichtung\nKosten:\n35\n\nKlassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Spurt' hinterlässt nun eine Spur von Blättern.\n11" }
entries[225534] = { ["name"] = "Glyphe 'Herbstliches Wachstum'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)\nStellt eine Glyphe 'Herbstliches Wachstum' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nLässt Euer 'Blühendes Leben' zu einer üppigen Herbstblume aufblühen.\n11" }
entries[225535] = { ["name"] = "Glyphe 'Arachnophobie'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)\nStellt eine Glyphe 'Arachnophobie' her.\nBeute von:\nWeltkreaturen der Verheerten Inseln\n\nKlassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBei Eurem Einsatz von 'Alphatier' werden öfter Spinnen herbeigerufen. Warum? Weil einfach jeder Angst vor Spinnen hat. Exklusiv mit: Glyphe 'Nesingwarys Nemesis' Glyphe 'Alpharudel' Glyphe 'Killerbienen'\n11" }
entries[225536] = { ["name"] = "Glyphe 'Nesingwarys Nemesis'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)\nStellt eine Glyphe 'Nesingwarys Nemesis' her.\nVerkäufer:\nLukas Sigmund\nZone:\nDer Hochberg\nKosten:\n35\n\nKlassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nBei Eurem Einsatz von 'Alphatier' werden oft Wildtiere herbeigerufen, die für gewöhnlich Opfer des berühmten Jägers sind. Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Alpharudel' Glyphe 'Killerbienen'\n11" }
entries[225538] = { ["name"] = "Glyphe 'Alpharudel'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)\nStellt eine Glyphe 'Alpharudel' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer 'Alphatier' ruft häufig Alphavarianten Eurer Begleiter im Stall herbei. Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Nesingwarys Nemesis' Glyphe 'Killerbienen'\n11" }
entries[225539] = { ["name"] = "Glyphe 'Goblinisches Antigravitationsleuchtfeuer'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)\nStellt eine Glyphe 'Goblinisches Antigravitationsleuchtfeuer' her.\nVerkäufer:\nHobart Wurfhammer\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nTauscht Eure Leuchtfeuer gegen goblinische Antigravitationsleuchtfeuer! Sie funktionieren sogar fast, und immerhin explodieren sie nicht. Exklusiv mit: Glyphe 'Sterneneruption'\n11" }
entries[225541] = { ["name"] = "Glyphe 'Haken'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)\nStellt eine Glyphe 'Haken' her.\nBeute von:\nMurlocs der Verheerten Inseln\n\nKlassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Harpune' zeigt einen Greifhaken anstelle Eurer angelegten Waffe an. Exklusiv mit: Glyphe 'Dreizack'\n11" }
entries[225543] = { ["name"] = "Glyphe 'Dreizack'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (8), Rosenrote Pigmente (40)\nStellt eine Glyphe 'Dreizack' her.\nBeute von:\nNaga der Verheerten Inseln\n\nKlassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Harpune' zeigt einen Dreizack anstelle Eurer angelegten Waffe an. Exklusiv mit: Glyphe 'Haken'\n11" }
entries[225545] = { ["name"] = "Glyphe 'Verwandlungsform'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (6), Rosenrote Pigmente (50)\nStellt eine Glyphe 'Verwandlungsform' her.\nBeute von:\nDer Rattenkönig\nZone:\nDer Arkus\n\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Verwandlungen sind etwas größer.\n11" }
entries[225546] = { ["name"] = "Glyphe 'Qualmen'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (6), Rosenrote Pigmente (50)\nStellt eine Glyphe 'Qualmen' her.\nBeute von:\nFeuer- und Erdelementare der Verheerten Inseln\n\nKlassen: Magier\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nNach dem Einsatz von 'Einäschern' qualmt ihr nun für einige Sekunden.\n11" }
entries[225547] = { ["name"] = "Glyphe 'Yu'lons Anmut'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (4), Rosenrote Pigmente (60)\nStellt eine Glyphe 'Yu'lons Anmut' her.\nVerkäufer:\nJang Federpfote\nZone:\nDalaran\nKosten:\n35\n\nKlassen: Mönch\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nÄndert die Farbe der Kugeln Eurer 'Gabe des Ochsen' in das Grün von Yu'lon.\n11" }
entries[225548] = { ["name"] = "Glyphe 'Brandeilig'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (10), Rosenrote Pigmente (30)\nStellt eine Glyphe 'Brandeilig' her.\nVerkäufer:\nCravitz Lorent\nZone:\nKristallsangwald\nZone:\nKanalisation von Dalaran\nKosten:\n35\n\nKlassen: Schurke\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Sprinten' hinterlässt eine Rauchfahne.\n11" }
entries[225549] = { ["name"] = "Glyphe 'Blendgranate'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (10), Rosenrote Pigmente (30)\nStellt eine Glyphe 'Blendgranate' her.\nVerkäufer:\nDie Witwe\nZone:\nKanalisation von Dalaran\nKosten:\n100\n\nKlassen: Schurke\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nTauscht Euren Rauch gegen eine Blendgranate!\n11" }
entries[225550] = { ["name"] = "Glyphe 'Kleintierverhexung'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (6), Rosenrote Pigmente (50)\nStellt eine Glyphe 'Kleintierverhexung' her.\nVerkäufer:\nK'huta\nZone:\nKanalisation von Dalaran\nKosten:\n100\n\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\n'Verhexen' hält bei Kleintieren jetzt 1 Tag lang an und lässt sich auf mehrere Kleintiere wirken.\n11" }
entries[225551] = { ["name"] = "Glyphe 'Flackern'", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (6), Rosenrote Pigmente (50)\nStellt eine Glyphe 'Flackern' her.\nVerkäufer:\nElementaristin Sharvak\nZone:\nNagrand\nKosten:\n35\n\nKlassen: Schamane\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Größe Eures Feuerelementars um 15%.\n11" }
