entries[225553] = { ["name"] = "Grimoire des Abyssals", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (2), Rosenrote Pigmente (70)\nStellt ein Grimoire des Abyssals her.\nBeute von:\nGul'dan\nZone:\nNachtfestung\n\nGrimoire des Abyssals\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den Abyssal beim Barbier frei.\n11" }
