entries[225556] = { ["name"] = "Grimoire der Shivarra", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)\nStellt ein Grimoire der Shivarra her.\nBeute von:\nHumanoide Dämonen der Verheerten Inseln\n\nGrimoire der Shivarra\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für die Shivarra beim Barbier frei.\n11" }
