entries[225559] = { ["name"] = "Grimoire des Zornwächters", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)\nStellt ein Grimoire des Zornwächters her.\nVerkäufer:\nKriegsmagierin Kath'leen\nZone:\nDie Verheerte Küste\nKosten:\n2500\n\nGrimoire des Zornwächters\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den Zornwächter beim Barbier frei.\n11" }
