entries[225575] = { ["name"] = "Champion: Thassarian", ["text"] = "Sofort\nEs gibt nur wenige unter den Rittern der Schwarzen Klinge, die mehr Loyalität bewiesen haben als Thassarian. Seine standhafte Überzeugung und sein Kampfgeschick haben ihm den Respekt aller Ordensmitglieder eingebracht." }
