entries[225577] = { ["name"] = "Champion: Nazgrim", ["text"] = "Sofort\nIm Leben war Nazgrim einer der größten Generäle der Horde. Im Tod ist er ein mächtiger Champion der Schwarzen Klinge. Nur wenige, ob lebendig oder tot, können sich im Kampf mit ihm messen." }
