entries[225580] = { ["name"] = "Champion: Koltira", ["text"] = "Sofort\nIn den Reihen der Schwarzen Klinge gibt es nur wenige Todesritter, die es mit Koltira Todeswebers Schnelligkeit und Beweglichkeit aufnehmen können. Seine Fähigkeiten im Umgang mit der Runenklinge sind legendär." }
