entries[225586] = { ["name"] = "Eiswasser herbeizaubern", ["text"] = "Wirken in 3 sek.\nZaubert Manaspeisen herbei, die den Magier sowie seine Verbündeten mit etwas Essbarem versorgen. Herbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[225587] = { ["name"] = "Champion: Thoras Trollbann", ["text"] = "Sofort\nIn den Annalen der Geschichte gibt es nur wenige Krieger, die so legendenreich sind wie König Thoras Trollbann. Als König wurde er respektiert. Als Todesritter von den Vier Reitern wird er gefürchtet werden." }
