entries[225590] = { ["name"] = "Implosion", ["text"] = "100 Meter Reichweite\nSofort\nDämonische Kräfte ziehen alle Eure Wildwichtel zum Ziel hin und lassen sie gewaltsam explodieren, wodurch sie allen Gegnern innerhalb von 8 Metern (54.5531% der Zaubermacht) Schattenflammenschaden zufügen." }
